//! Tests against the committed generated RPC error catalog
//! (src/rpc/errors_gen.zig, regenerated by `just errors` from the
//! vendored TSVs in tests/data/rpc_errors/): wire-message
//! classification, parameterized normalization, table invariants, and
//! the rpc/dc integration built on top of it.

const std = @import("std");
const td = @import("td");

const errors_gen = td.rpc.errors_gen;

test "classify: exact non-parameterized ids" {
    const c = errors_gen.classify("PHONE_CODE_INVALID").?;
    try std.testing.expect(c.id == .phone_code_invalid);
    try std.testing.expect(c.value == null);
    try std.testing.expectEqualStrings("PHONE_CODE_INVALID", c.id.wire());
    try std.testing.expect(!c.id.parameterized());
    try std.testing.expect(c.id.description().len > 0);
}

test "classify: parameterized normalization extracts the number" {
    const flood = errors_gen.classify("FLOOD_WAIT_60").?;
    try std.testing.expect(flood.id == .flood_wait_x);
    try std.testing.expectEqual(@as(u32, 60), flood.value.?);
    try std.testing.expect(flood.id.parameterized());
    try std.testing.expectEqualStrings("FLOOD_WAIT_X", flood.id.wire());

    const migrate = errors_gen.classify("PHONE_MIGRATE_4").?;
    try std.testing.expect(migrate.id == .phone_migrate_x);
    try std.testing.expectEqual(@as(u32, 4), migrate.value.?);

    // Digit-leading family.
    const confirm = errors_gen.classify("2FA_CONFIRM_WAIT_99").?;
    try std.testing.expect(confirm.id == .@"2fa_confirm_wait_x");
    try std.testing.expectEqual(@as(u32, 99), confirm.value.?);

    // Zero stays zero; rejecting it is the migration layer's call.
    const zero = errors_gen.classify("FLOOD_WAIT_0").?;
    try std.testing.expectEqual(@as(u32, 0), zero.value.?);

    // A plain id and its parameterized twin are distinct entries.
    const plain = errors_gen.classify("AUTH_RESTART").?;
    try std.testing.expect(plain.id == .auth_restart);
    try std.testing.expect(plain.value == null);
    const twin = errors_gen.classify("AUTH_RESTART_3").?;
    try std.testing.expect(twin.id == .auth_restart_x);
    try std.testing.expectEqual(@as(u32, 3), twin.value.?);
}

test "classify: unknown and malformed messages return null" {
    for ([_][]const u8{
        "",                       // empty
        "TOTALLY_UNKNOWN_ERROR",  // not in the catalog
        "FLOOD_WAIT_",            // no digits after the underscore
        "FLOOD_WAIT_60X",         // trailing junk after the digits
        "FLOOD_WAIT_9999999999",  // exceeds the u32-safe digit bound
        "PHONE_CODE_INVALID_5",   // suffix family not in the catalog
        "_60",                    // empty prefix
    }) |msg| try std.testing.expect(errors_gen.classify(msg) == null);
}

test "catalog invariants: tags, wires and ordering agree" {
    @setEvalBranchQuota(20000);
    const fields = @typeInfo(errors_gen.Id).@"enum".fields;
    try std.testing.expectEqual(errors_gen.count, fields.len);
    var prev: []const u8 = "";
    inline for (@typeInfo(errors_gen.Id).@"enum".fields, 0..) |f, i| {
        const id: errors_gen.Id = @enumFromInt(i);
        // Tag is the lowercased wire id.
        try std.testing.expectEqualStrings(f.name, @tagName(id));
        try std.testing.expect(std.ascii.eqlIgnoreCase(f.name, id.wire()));
        // Wires are unique and sorted (binary-searchable).
        try std.testing.expect(std.mem.order(u8, prev, id.wire()) == .lt);
        prev = id.wire();
        // Every catalog id classifies as itself.
        const c = errors_gen.classify(id.wire()).?;
        try std.testing.expect(c.id == id);
        // Parameterized flag follows the `_X` suffix.
        try std.testing.expectEqual(std.mem.endsWith(u8, id.wire(), "_X"), id.parameterized());
    }
}

test "floodWaitSeconds over hand-built infos" {
    try std.testing.expectEqual(@as(u32, 60), td.rpc.floodWaitSeconds(.{ .code = 420, .message = "FLOOD_WAIT_60" }).?);
    try std.testing.expectEqual(@as(u32, 30), td.rpc.floodWaitSeconds(.{ .code = 420, .message = "FLOOD_PREMIUM_WAIT_30" }).?);
    try std.testing.expect(td.rpc.floodWaitSeconds(.{ .code = 400, .message = "PHONE_CODE_INVALID" }) == null);
    try std.testing.expect(td.rpc.floodWaitSeconds(.{ .code = 420, .message = "SLOWMODE_WAIT_60" }) == null);
    try std.testing.expect(td.rpc.floodWaitSeconds(.{ .code = 0, .message = "" }) == null);
}

test "dc migration classifies through the catalog" {
    const m = td.dc.migration.fromRpcError(.{ .code = 303, .message = "PHONE_MIGRATE_4" }).?;
    try std.testing.expect(m.kind == .phone);
    try std.testing.expectEqual(@as(i32, 4), m.dc);

    // Value policing stays in the migration layer.
    try std.testing.expect(td.dc.migration.fromRpcError(.{ .code = 303, .message = "PHONE_MIGRATE_0" }) == null);
    // Only the four classic redirect kinds; STATS_MIGRATE_X is cataloged
    // but not a migration this layer acts on.
    try std.testing.expect(td.dc.migration.fromRpcError(.{ .code = 303, .message = "STATS_MIGRATE_1" }) == null);
}
